    (NAME(ZENITH.CUST.MASTER.FILE)                       -
     CYLINDERS(1 1)                                      -
     RECORDSIZE(80 80)                                   -
     INDEXED                                             -
     KEYS(8 0)                                           -
     SHAREOPTIONS(2 3))
